import type { TableName, TableSchemaDotWalk } from '../db'

/**
 * Type representing the rule to be performed on a field by a Data Policy.
 * Rule properties use boolean or 'ignore' format.
 * For cross-table enforcement, use dot-walk notation in the rule key (e.g., 'employee.department').
 */
export type DataPolicyRuleConfig = Now.Internal.WithID<{
    /** How the data policy affects the mandatory state of the field */
    mandatory?: boolean | 'ignore'
    /** How the data policy affects the read-only state of the field */
    readOnly?: boolean | 'ignore'
    /** The table on which the data policy rule applies. If not specified, inherits from parent Data Policy */
    table?: TableName
}>

/**
 * Type representing the complete configuration of a Data Policy with metadata.
 * @interface
 */
export type DataPolicy<T extends TableName> = Now.Internal.WithIdAndMetadata<{
    /** The table to which the Data Policy applies (required) */
    table: T
    /** A brief description of the Data Policy's purpose */
    shortDescription?: string
    /** Whether the Data Policy is active */
    active?: boolean
    /** If true, enforces policy rules during import set transformations */
    applyToImportSets?: boolean
    /** If true, enforces policy rules for SOAP/REST web service operations */
    applyToSOAP?: boolean
    /** Encoded query string defining when the policy applies */
    conditions?: string
    /** Detailed description of the Data Policy's purpose */
    description?: string
    /** If true, also enforces as UI Policy on client side for immediate user feedback */
    useAsUiPolicyOnClient?: boolean
    /** If true, applies this policy to all tables that extend the target table */
    inherit?: boolean
    /** Document ID reference for model-based policies */
    modelId?: string
    /** If true, reverses the policy rules when condition is false */
    reverseIfFalse?: boolean
    /**
     * Field-level rules (mandatory, read-only) keyed by field name. Each field can only have one rule.
     *
     * Type Safety Trade-off:
     * - The `Partial<Record<TableSchemaDotWalk<T>, ...>>` part provides type safety and autocomplete for fields in the main table
     * - The `& Record<string, ...>` index signature allows cross-table dot-walk notation (e.g., 'employee.department')
     *   and rules with explicit `table` properties that reference fields outside the main table
     *
     * This design prioritizes flexibility for cross-table rules over strict type safety, as Data Policies
     * commonly need to enforce rules on fields in referenced tables that cannot be statically validated.
     */
    rules?: Partial<Record<TableSchemaDotWalk<T>, DataPolicyRuleConfig>> & Record<string, DataPolicyRuleConfig>
}>

/**
 * Creates a Data Policy that enforces field mandatory status and read-only behavior on forms and lists,
 * regardless of user interface. Data Policies are server-side and apply across all interfaces
 * (forms, lists, mobile, web services, import sets, integrations).
 *
 * @see https://docs.servicenow.com/csh?topicname=data-policy-api-now-ts.html&version=latest
 *
 * @param config - an object containing api properties
 */
export function DataPolicy<const T extends TableName>(config: DataPolicy<T>): DataPolicy<T> {
    return config
}
